public class VideoRecommendationService
{
    public IEnumerable<Video> GetRecommended(Guid userId)
    {
        var watched = _watchHistory.GetHistory(userId).Select(h => h.VideoId).ToHashSet();
        var subscriptions = _subscriptions.GetSubscribedChannels(userId).Select(s => s.ChannelId).ToHashSet();

        return _videos
            .Where(v => !watched.Contains(v.Id) && subscriptions.Contains(v.ChannelId))
            .OrderByDescending(v => v.ViewCount)
            .Take(20);
    }
}

public class AdService
{
    public AdCampaign CreateCampaign(Guid videoId, decimal cpm, string targetAudience)
    {
        return new AdCampaign
        {
            VideoId = videoId,
            Cpm = cpm,
            TargetAudience = targetAudience,
            Impressions = 0,
            Clicks = 0
        };
    }

    public void TrackImpression(Guid campaignId)
    {
        var campaign = _campaigns[campaignId];
        campaign.Impressions++;
        campaign.Revenue += campaign.Cpm / 1000m;
    }
}
